INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(201, 'Genesis 8:21', 'Genesis', 8, 21, '&nbsp;د قربانۍ په خوشبو مالِک خُدائ رضا شو او خپل ځان سره يې وفرمائيل، ”د بنى آدم د عمل په وجه به بيا زۀ هيڅکله زمکه نۀ لعنتى کوم، ما ته پته ده چې د ماشوموالى نه د دوئ خيالونه خراب وى. بيا به ټول مخلوق تباه نۀ کړم، لکه چې دا ځل مې تباه کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(202, 'Genesis 8:22', 'Genesis', 8, 22, '&nbsp;چې تر کومې پورې دُنيا موجوده وى، کَرل او رېبل به وى، يخنى او ګرمى به وى، اوړے او ژمے به وى، شپه او ورځ به وى د دُنيا تر آخره پورې به وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(203, 'Genesis 9:1', 'Genesis', 9, 1, '&nbsp;خُدائ پاک نوح او د هغۀ زامنو له برکت ورکړو او وې فرمائيل، ”آباد شئ او ډېر بچى پېدا کړئ، نو ستاسو اولاد به په ټوله دُنيا کښې اوسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(204, 'Genesis 9:2', 'Genesis', 9, 2, '&nbsp;ټول ځناور، مارغان، خزنده او کبان به ستاسو نه يريږى، دا ټول ستاسو د اختيار لاندې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(205, 'Genesis 9:3', 'Genesis', 9, 3, '&nbsp;اوس دا ټول ځناور تاسو خوړلے شئ او دغه شان شنۀ بوټى هم، دا ټول ستاسو د خوراک دپاره دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(206, 'Genesis 9:4', 'Genesis', 9, 4, '&nbsp;خو چې په کومه غوښه کښې وينه وى هغه به نۀ خورئ، دا ستاسو دپاره منع ده ځکه چې په وينه کښې ژوندون دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(207, 'Genesis 9:5', 'Genesis', 9, 5, '&nbsp;کۀ څوک بل کس قتلوى، زۀ به ورسره حِساب کوم. کۀ يو ځناور بنى آدم ووژنى نو سزا به يې مرګ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(208, 'Genesis 9:6', 'Genesis', 9, 6, '&nbsp;ځکه چې خُدائ پاک د خپل ځان په شان بنى آدم جوړ کړے دے. کۀ څوک د بنى آدم وينه تويَوى، په بدل کښې به د هغۀ وينه توئ کړے شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(209, 'Genesis 9:7', 'Genesis', 9, 7, '&nbsp;ډېر بچى پېدا کړئ، نو چې ستاسو اولاد به په ټوله دُنيا کښې اوسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(210, 'Genesis 9:8', 'Genesis', 9, 8, '&nbsp;خُدائ پاک نوح او د هغۀ زامنو ته وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(211, 'Genesis 9:9', 'Genesis', 9, 9, '&nbsp;”ګورئ، اوس زۀ تاسو او ستاسو د اولاد سره دا لوظ کوم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(212, 'Genesis 9:10', 'Genesis', 9, 10, '&nbsp;هم داسې د هر ژوندى څيز، د ټولو مارغانو، ځناورو او هر هغه څيز سره چې ستاسو سره د کشتۍ نه رابهر شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(213, 'Genesis 9:11', 'Genesis', 9, 11, '&nbsp;زۀ تاسو سره د دې خبرې لوظ کوم، چې بيا به هيڅکله هم ټول ژوندى مخلوقات په سېلاب نۀ غرقيږى، بيا به په سېلاب دُنيا نۀ تباه کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(214, 'Genesis 9:12', 'Genesis', 9, 12, '&nbsp;دا نښه به نۀ ختمېدونکے لوظ وى کوم چې زۀ ستا او د ټولو ژوندو څيزونو سره کوم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(215, 'Genesis 9:13', 'Genesis', 9, 13, '&nbsp;زۀ به په آسمان کښې د بوډۍ ټال جوړوم. دا به زما د دُنيا سره د لوظ نښه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(216, 'Genesis 9:14', 'Genesis', 9, 14, '&nbsp;چې کله هم زۀ په زمکه وريځې راولم او چې د بوډۍ ټال په وريځو کښې راڅرګنديږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(217, 'Genesis 9:15', 'Genesis', 9, 15, '&nbsp;نو ما ته به خپل لوظ راياديږى چې سېلاب به بيا هيڅکله ټول ژوندى څيزونه نۀ تباه کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(218, 'Genesis 9:16', 'Genesis', 9, 16, '&nbsp;چې کله په وريځو کښې د بوډۍ ټال څرګند شى، زۀ به ورته ګورم او هغه نۀ ختمېدونکے لوظ به رايادوم کوم چې ما د زمکې د ټولو ژوندو څيزونو سره کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(219, 'Genesis 9:17', 'Genesis', 9, 17, '&nbsp;دا زما د هغه لوظ نښه ده کوم چې زۀ د دُنيا د ټولو ژوندو مخلوقاتو سره کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(220, 'Genesis 9:18', 'Genesis', 9, 18, '&nbsp;د نوح زامن چې د کشتۍ نه کوز شول هغوئ شيم، حام او يافت وُو. (حام د کنعان پلار وو.)', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(221, 'Genesis 9:19', 'Genesis', 9, 19, '&nbsp;په زمکه چې څومره خلق دى دا ټول د نوح د درېو زامنو اولاد دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(222, 'Genesis 9:20', 'Genesis', 9, 20, '&nbsp;نوح زميدار وو، هغه وړومبے کس وو چې د انګورو باغ يې وکَرلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(223, 'Genesis 9:21', 'Genesis', 9, 21, '&nbsp;د ميو څښلو نه پس هغه نشه شو او په خپله خېمه کښې بربنډ څملاستو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(224, 'Genesis 9:22', 'Genesis', 9, 22, '&nbsp;چې کله د کنعان پلار حام، خپل پلار داسې وليدو نو هغه بهر لاړو او خپل دوه وروڼه يې خبر کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(225, 'Genesis 9:23', 'Genesis', 9, 23, '&nbsp;نو شيم او يافت يو څادر واخستو او د خپلو اوږو شا ته يې ونيولو. او خېمې ته په شا دننه لاړل او خپل پلار يې پټ کړو او مخونه يې اړولى وُو چې پلار بربنډ ونۀ ګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(226, 'Genesis 9:24', 'Genesis', 9, 24, '&nbsp;چې کله نوح په خود کښې شو او خبر شو چې د ټولو کشرى زوئ د هغۀ سره څۀ کړى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(227, 'Genesis 9:25', 'Genesis', 9, 25, '&nbsp;نو هغۀ وفرمائيل چې، ”په کنعان دې لعنت وى، هغه دې د ټولو وروڼو د نوکرانو غلام شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(228, 'Genesis 9:26', 'Genesis', 9, 26, '&nbsp;مالِک خُدائ دې شيم بختور کړى، او کنعان دې د هغۀ غلام کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(229, 'Genesis 9:27', 'Genesis', 9, 27, '&nbsp;خُدائ پاک دې يافت ډېر تېر کړى، د هغۀ اولاد او د شيم خلق دې د وروڼو په شان کړى، او کنعان دې د هغۀ غلام کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(230, 'Genesis 9:28', 'Genesis', 9, 28, '&nbsp;د سېلاب نه پس نوح نور درې نيم سوه کاله ژوندے وو', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(231, 'Genesis 9:29', 'Genesis', 9, 29, '&nbsp;او د نهۀ نيم سوو کالو په عُمر کښې په حق ورسېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(232, 'Genesis 10:1', 'Genesis', 10, 1, '&nbsp;دا د نوح د زامنو، د شيم، حام او يافت اولاد دے، چې د سېلاب نه پس د هغوئ زامن پېدا شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(233, 'Genesis 10:2', 'Genesis', 10, 2, '&nbsp;دا د يافت اولاد دے، جُمر، ماجوج، مادى، ياوان، توبل، مسک او تيراس.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(234, 'Genesis 10:3', 'Genesis', 10, 3, '&nbsp;دا د جُمر اولاد دے، اشکناز، ريفت او تُجرمه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(235, 'Genesis 10:4', 'Genesis', 10, 4, '&nbsp;دا د ياوان اولاد دے، اِليسه، ترسيس، قبرص او رهودس.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(236, 'Genesis 10:5', 'Genesis', 10, 5, '&nbsp;د دوئ اولاد د سمندر په غاړه او په جزيرو کښې اوسيږى. دا د يافت اولاد دے، چې په بېلو بېلو قبيلو او مُلکونو کښې اوسيږى او هره قبيله خپله خپله ژبه وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(237, 'Genesis 10:6', 'Genesis', 10, 6, '&nbsp;دا د حام اولاد دے، کوش، مِصر، ليبيا او کنعان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(238, 'Genesis 10:7', 'Genesis', 10, 7, '&nbsp;د کوش اولاد د سِيبا، حويله، سبته، راماه او د سبتيکه خلق دى. د راماه اولاد د شيبا او د ددان خلق دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(239, 'Genesis 10:8', 'Genesis', 10, 8, '&nbsp;کوش د نمرود پلار وو، نمرود د دُنيا وړومبے طاقتور جنګيالے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(240, 'Genesis 10:9', 'Genesis', 10, 9, '&nbsp;د مالِک خُدائ په مدد هغه يو لوئ ښکارى وو، نو ځکه خلق وائى، ”مالِک خُدائ دې د نمرود په شان لوئ ښکارى کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(241, 'Genesis 10:10', 'Genesis', 10, 10, '&nbsp;د هغۀ بادشاهى وړومبے په بابل، ارک او اِکاد وه، دا درې واړه د بابل په مُلک کښې وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(242, 'Genesis 10:11', 'Genesis', 10, 11, '&nbsp;د دې مُلک نه هغه اسور ته لاړو او د نينوه، رحوبوت عير، کلح،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(243, 'Genesis 10:12', 'Genesis', 10, 12, '&nbsp;او د رسن ښارونه يې جوړ کړل، رسن د نينوه او د لوئ ښار کلح په مينځ کښې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(244, 'Genesis 10:13', 'Genesis', 10, 13, '&nbsp;د مِصر اولاد د لودى، عنامى، لهابى، نفتوحى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(245, 'Genesis 10:14', 'Genesis', 10, 14, '&nbsp;فتروسى، کسلوحى او د کريت خلق وُو، چې د هغوئ اولاد فلستيان دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(246, 'Genesis 10:15', 'Genesis', 10, 15, '&nbsp;د کنعان مشرے زوئ صيدا وو. کنعان د دې قومونو هم پلار وو، حت،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(247, 'Genesis 10:16', 'Genesis', 10, 16, '&nbsp;يبوسى، امورى، جرجاسى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(248, 'Genesis 10:17', 'Genesis', 10, 17, '&nbsp;حِوى، عرقى، سينى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(249, 'Genesis 10:18', 'Genesis', 10, 18, '&nbsp;اروادى، صمارى او حماتى. وروستو بيا د کنعانيانو قبيلې خورې شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(250, 'Genesis 10:19', 'Genesis', 10, 19, '&nbsp;د کنعانيانو مُلک شمالى طرف صيدا نه جرار ته نزدې، تر غزه پورې ورسېدو او نمرخاتۀ طرف سدوم ته، عموره، ادمه او لَسَع ته، چې ضبوئيم ته نزدې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(251, 'Genesis 10:20', 'Genesis', 10, 20, '&nbsp;دا د حام اولاد دے، چې په بېلو بېلو قبيلو او مُلکونو کښې اوسيږى او هره قبيله خپله خپله ژبه وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(252, 'Genesis 10:21', 'Genesis', 10, 21, '&nbsp;ټول عبرانيان د شيم اولاد دے، شيم د يافت مشر ورور دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(253, 'Genesis 10:22', 'Genesis', 10, 22, '&nbsp;دا د شيم اولاد دے، عيلام، اسور، ارفکسد، لود او آرام.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(254, 'Genesis 10:23', 'Genesis', 10, 23, '&nbsp;د آرام اولاد عُوض، حُول، جتر او مس وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(255, 'Genesis 10:24', 'Genesis', 10, 24, '&nbsp;ارفکسد د سِلح پلار وو او سِلح د عِبر پلار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(256, 'Genesis 10:25', 'Genesis', 10, 25, '&nbsp;د عِبر دوه زامن وُو، د يو نوم فلج چې مطلب يې تقسيم وو، ځکه چې د هغۀ په وخت کښې د دُنيا خلق تقسيم شول. او د بل نوم يُقطان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(257, 'Genesis 10:26', 'Genesis', 10, 26, '&nbsp;د يُقطان اولاد د الموداد، سلف، حصارماوت، اِراخ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(258, 'Genesis 10:27', 'Genesis', 10, 27, '&nbsp;هدورام، اُوزال، دِقله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(259, 'Genesis 10:28', 'Genesis', 10, 28, '&nbsp;عوبال، ابى‌مائيل، شيبا،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(260, 'Genesis 10:29', 'Genesis', 10, 29, '&nbsp;اوفير، حويله او يوباب. دا ټول د يُقطان اولاد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(261, 'Genesis 10:30', 'Genesis', 10, 30, '&nbsp;چې دوئ په کوم مُلک کښې اوسېدل هغه مُلک د ميسا نه سِفار پورې اوږد وو چې نمرخاتۀ طرف ته د غرونو په مُلک کښې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(262, 'Genesis 10:31', 'Genesis', 10, 31, '&nbsp;دا د شيم اولاد دے، چې په بېلو بېلو قبيلو او مُلکونو کښې اوسيږى او هره قبيله خپله خپله ژبه وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(263, 'Genesis 10:32', 'Genesis', 10, 32, '&nbsp;دا ټول خلق نسل در نسل، د بېلو بېلو نسب‌نامو په مطابق د نوح اولاد دے. د سېلاب نه پس د دُنيا ټول قومونه د نوح د زامنو اولاد دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(264, 'Genesis 11:1', 'Genesis', 11, 1, '&nbsp;په شروع کښې، د ټولې دُنيا خلقو صِرف يوه ژبه وئيله او د يو بل په خبرو پوهېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(265, 'Genesis 11:2', 'Genesis', 11, 2, '&nbsp;چې څنګه دوئ د نمرخاتۀ غاړې نه روان شول، چې چرته دوئ اوسېدل، نو د بابل په مُلک کښې يو هوار مېدان ته راغلل او هلته دېره شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(266, 'Genesis 11:3', 'Genesis', 11, 3, '&nbsp;دوئ يو بل ته ووئيل، ”راځئ چې خَښتې جوړې کړُو او په اور يې پخې کړُو.“ نو داسې د دوئ سره د آبادۍ دپاره خَښتې او د دې د انښلولو دپاره تارکول وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(267, 'Genesis 11:4', 'Genesis', 11, 4, '&nbsp;نو دوئ ووئيل، ”راځئ چې اوس يو ښار او دومره لوئ برج جوړ کړُو چې آسمان ته ورسيږى، نو مونږ به مشهور شُو او په ټوله دُنيا کښې به خوارۀ وارۀ هم نۀ شُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(268, 'Genesis 11:5', 'Genesis', 11, 5, '&nbsp;بيا مالِک خُدائ د ښار او هغه برج کتلو له راکوز شو چې بنيادمو جوړ کړے وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
